public sealed class PayrollConcurrencyMatrixTests
{
    [Fact]
    public async Task Period_lock_competition_has_one_effective_transition()
    {
        using var database = new SqliteInMemoryDatabase(); var tenantId = Guid.NewGuid(); await AddTenant(database, tenantId);
        await using var db = database.CreateContext(new TestTenantContext(tenantId)); var service = new PayrollPeriodService(db, new TestTenantContext(tenantId), TimeProvider.System); var created = await service.CreateAsync(Period("CON-PERIOD")); var opened = await service.TransitionAsync(created.Value!.Id, "open", created.Value.ConcurrencyVersion); var closed = await service.TransitionAsync(created.Value.Id, "close", opened.Value!.ConcurrencyVersion); var version = closed.Value!.ConcurrencyVersion;
        async Task<bool> Lock() { await using var c = database.CreateContext(new TestTenantContext(tenantId)); try { return (await new PayrollPeriodService(c, new TestTenantContext(tenantId), TimeProvider.System).TransitionAsync(created.Value.Id, "lock", version, "concurrent")).Succeeded; } catch (DbUpdateConcurrencyException) { return false; } }
        Assert.Equal(1, (await Task.WhenAll(Lock(), Lock())).Count(x => x)); await using var verify = database.CreateContext(new TestTenantContext(tenantId)); Assert.Equal(PayrollPeriodStatus.Locked, (await verify.PayrollPeriods.SingleAsync(x => x.Id == created.Value.Id)).Status); Assert.Equal(1, await verify.PayrollPeriodHistories.CountAsync(x => x.PayrollPeriodId == created.Value.Id && x.ChangeType == "Locked"));
    }

    [Fact]
    public async Task Payroll_run_approval_competition_has_one_effective_transition()
    {
        using var database = new SqliteInMemoryDatabase(); var tenantId = Guid.NewGuid(); var runId = Guid.NewGuid(); await AddTenant(database, tenantId); await using (var db = database.CreateContext(new TestTenantContext(tenantId))) { var period = new PayrollPeriod { Id = Guid.NewGuid(), TenantId = tenantId, Code = "CON-RUN", Name = "Concurrent", PeriodType = PayrollPeriodType.Monthly, StartDate = new DateOnly(2026, 9, 1), EndDate = new DateOnly(2026, 9, 30), PayDate = new DateOnly(2026, 10, 5), Status = PayrollPeriodStatus.Open }; db.PayrollPeriods.Add(period); db.PayrollRuns.Add(new PayrollRun { Id = runId, TenantId = tenantId, PayrollPeriodId = period.Id, RunNumber = "CON-RUN-1", Status = PayrollRunStatus.Calculated }); await db.SaveChangesAsync(); }
        async Task<bool> Approve() { await using var c = database.CreateContext(new TestTenantContext(tenantId)); try { return (await new PayrollRunService(c, new TestTenantContext(tenantId), TimeProvider.System).TransitionAsync(runId, PayrollRunStatus.Approved)).Succeeded; } catch (DbUpdateConcurrencyException) { return false; } }
        Assert.Equal(1, (await Task.WhenAll(Approve(), Approve())).Count(x => x)); await using var verify = database.CreateContext(new TestTenantContext(tenantId)); Assert.Equal(1, await verify.PayrollRunHistories.CountAsync(x => x.PayrollRunId == runId && x.ChangeType == PayrollRunHistoryChangeType.Approved));
    }

    [Fact]
    public async Task Bank_advice_approval_competition_has_one_effective_transition()
    {
        using var database = new SqliteInMemoryDatabase(); var ids = await SeedBank(database); await using (var db = database.CreateContext(new TestTenantContext(ids.TenantId))) { var service = new BankAdviceService(db, new TestTenantContext(ids.TenantId), TimeProvider.System); var generated = await service.GenerateAsync(ids.RunId); Assert.True(generated.Succeeded, generated.Message); Assert.True((await service.PrepareAsync(generated.Value!.Id)).Succeeded); ids = ids with { BatchId = generated.Value.Id }; }
        async Task<bool> Approve() { await using var c = database.CreateContext(new TestTenantContext(ids.TenantId)); try { return (await new BankAdviceService(c, new TestTenantContext(ids.TenantId), TimeProvider.System).ApproveAsync(ids.BatchId)).Succeeded; } catch (DbUpdateConcurrencyException) { return false; } }
        Assert.Equal(1, (await Task.WhenAll(Approve(), Approve())).Count(x => x)); await using var verify = database.CreateContext(new TestTenantContext(ids.TenantId)); Assert.Equal(1, await verify.BankAdviceHistories.CountAsync(x => x.BankAdviceBatchId == ids.BatchId && x.ChangeType == BankAdviceHistoryChangeType.Approved));
    }

    [Fact]
    public async Task Accounting_generation_competition_has_one_active_journal()
    {
        using var database = new SqliteInMemoryDatabase(); var ids = await SeedAccounting(database); async Task<bool> Generate() { await using var c = database.CreateContext(new TestTenantContext(ids.TenantId)); try { return (await new PayrollAccountingService(c, new TestTenantContext(ids.TenantId), TimeProvider.System).GenerateAsync(ids.RunId)).Succeeded; } catch (DbUpdateException) { return false; } }
        Assert.Equal(1, (await Task.WhenAll(Generate(), Generate())).Count(x => x)); await using var verify = database.CreateContext(new TestTenantContext(ids.TenantId)); Assert.Equal(1, await verify.PayrollJournalBatches.CountAsync(x => x.PayrollRunId == ids.RunId));
    }

    [Fact]
    public async Task Statutory_return_generation_competition_has_one_active_return()
    {
        using var database = new SqliteInMemoryDatabase(); var ids = await SeedStatutory(database); async Task<bool> Generate() { await using var c = database.CreateContext(new TestTenantContext(ids.TenantId)); try { return (await new PayrollStatutoryComplianceService(c, new TestTenantContext(ids.TenantId), TimeProvider.System).GenerateAsync(ids.PeriodId)).Succeeded; } catch (DbUpdateException) { return false; } }
        var outcomes = await Task.WhenAll(Generate(), Generate()); Assert.True(outcomes.Count(x => x) <= 1); await using var verify = database.CreateContext(new TestTenantContext(ids.TenantId)); var batches = await verify.PayrollStatutoryReturnBatches.Where(x => x.PayrollCompliancePeriodId == ids.PeriodId && x.Status != PayrollStatutoryReturnStatus.Cancelled).ToListAsync(); Assert.Single(batches); Assert.Single(await verify.PayrollStatutoryReturnSources.Where(x => x.PayrollStatutoryReturnBatchId == batches[0].Id).ToListAsync()); Assert.Equal(1000m, batches[0].TotalPayable);
    }

    [Fact]
    public async Task Retro_apply_competition_with_non_zero_adjustment_has_one_application()
    {
        using var database = new SqliteInMemoryDatabase(); var ids = await SeedRetro(database);
        async Task<bool> Apply() { await using var c = database.CreateContext(new TestTenantContext(ids.TenantId)); try { return (await new PayrollRetroSettlementService(c, new TestTenantContext(ids.TenantId), TimeProvider.System).ApplyRetroAsync(ids.CaseId, ids.TargetRunId)).Succeeded; } catch (DbUpdateConcurrencyException) { return false; } catch (DbUpdateException) { return false; } }
        Assert.Equal(1, (await Task.WhenAll(Apply(), Apply())).Count(x => x)); await using var verify = database.CreateContext(new TestTenantContext(ids.TenantId)); Assert.Equal(PayrollRetroStatus.Applied, (await verify.PayrollRetroCases.SingleAsync(x => x.Id == ids.CaseId)).Status); var adjustments = await verify.PayrollAdjustments.Where(x => x.SourceType == nameof(PayrollRetroResult) && x.SourceId == ids.ResultId).ToListAsync(); Assert.Single(adjustments); Assert.Equal(100m, adjustments[0].Amount); Assert.Single(await verify.PayrollRetroHistories.Where(x => x.PayrollRetroCaseId == ids.CaseId && x.ChangeType == PayrollRetroHistoryChangeType.Applied).ToListAsync());
    }

    private sealed record Ids(Guid TenantId, Guid RunId, Guid BatchId = default, Guid PeriodId = default, Guid CaseId = default, Guid ResultId = default, Guid TargetRunId = default);
    private static PayrollPeriodRequest Period(string code) => new() { Code = code, Name = code, PeriodType = PayrollPeriodType.Monthly, StartDate = new DateOnly(2026, 9, 1), EndDate = new DateOnly(2026, 9, 30), PayDate = new DateOnly(2026, 10, 5), FiscalYear = 2026, PeriodNumber = 9 };
    private static async Task AddTenant(SqliteInMemoryDatabase database, Guid id) { await using var db = database.CreateContext(new TestTenantContext()); db.Tenants.Add(new Tenant { Id = id, TenantCode = $"C{id:N}"[..12], TenantName = "Concurrency", Host = $"{id:N}.test", ShardKey = id.ToString("N") }); await db.SaveChangesAsync(); }

    private static async Task<Ids> SeedStatutory(SqliteInMemoryDatabase database)
    {
        var t = Guid.NewGuid(); var e = Guid.NewGuid(); var period = Guid.NewGuid(); var run = Guid.NewGuid(); var runEmployee = Guid.NewGuid(); var result = Guid.NewGuid(); var assignment = Guid.NewGuid(); var structure = Guid.NewGuid(); var version = Guid.NewGuid(); var component = Guid.NewGuid(); var config = Guid.NewGuid(); var configVersion = Guid.NewGuid(); await AddTenant(database, t);
        await using var db = database.CreateContext(new TestTenantContext(t));
        db.Employees.Add(new Employee { Id = e, TenantId = t, EmployeeCode = "CON-STAT", FirstName = "Stat", LastName = "Concurrency", Email = $"{e:N}@test.local", DateOfJoining = new DateOnly(2025, 1, 1), Status = EmployeeStatus.Active, UanNumber = "UAN-CON-STAT" });
        db.SalaryComponents.Add(new SalaryComponent { Id = component, TenantId = t, Code = "CON-STAT-BASIC", Name = "Basic", ComponentType = SalaryComponentType.Earning, CalculationType = SalaryCalculationType.FixedAmount, EffectiveFrom = new DateOnly(2026, 1, 1), IsActive = true, AffectsGross = true, AffectsNetPay = true });
        db.SalaryStructures.Add(new SalaryStructure { Id = structure, TenantId = t, Code = "CON-STAT-S", Name = "Structure", IsActive = true }); db.SalaryStructureVersions.Add(new SalaryStructureVersion { Id = version, TenantId = t, SalaryStructureId = structure, EffectiveFrom = new DateOnly(2026, 1, 1), IsActive = true });
        db.EmployeeSalaryAssignments.Add(new EmployeeSalaryAssignment { Id = assignment, TenantId = t, EmployeeId = e, SalaryStructureId = structure, SalaryStructureVersionId = version, EffectiveFrom = new DateOnly(2026, 1, 1), MonthlyCtc = 10000, CurrencyCode = "INR", Status = EmployeeSalaryAssignmentStatus.Active });
        db.PayrollPeriods.Add(new PayrollPeriod { Id = period, TenantId = t, Code = "CON-STAT-P", Name = "Period", PeriodType = PayrollPeriodType.Monthly, StartDate = new DateOnly(2026, 9, 1), EndDate = new DateOnly(2026, 9, 30), PayDate = new DateOnly(2026, 10, 5), Status = PayrollPeriodStatus.Locked });
        db.PayrollRuns.Add(new PayrollRun { Id = run, TenantId = t, PayrollPeriodId = period, RunNumber = "CON-STAT-R", Status = PayrollRunStatus.Finalized }); db.PayrollRunEmployees.Add(new PayrollRunEmployee { Id = runEmployee, TenantId = t, PayrollRunId = run, EmployeeId = e, EmployeeSalaryAssignmentId = assignment, SalaryStructureId = structure, SalaryStructureVersionId = version, EmploymentSnapshotDate = new DateOnly(2026, 9, 30), IsEligible = true, Status = PayrollRunEmployeeStatus.Eligible });
        db.PayrollResults.Add(new PayrollResult { Id = result, TenantId = t, PayrollRunId = run, PayrollRunEmployeeId = runEmployee, EmployeeId = e, EmployeeSalaryAssignmentId = assignment, SalaryStructureId = structure, SalaryStructureVersionId = version, CalculationAttemptId = Guid.NewGuid(), PeriodStartDate = new DateOnly(2026, 9, 1), PeriodEndDate = new DateOnly(2026, 9, 30), EmploymentSnapshotDate = new DateOnly(2026, 9, 30), CalendarDays = 30, EligibleDays = 30, CurrencyCode = "INR", GrossEarnings = 10000, TotalDeductions = 1000, NetPay = 9000, Status = PayrollResultStatus.Calculated, IsCurrent = true });
        db.StatutoryConfigurations.Add(new StatutoryConfiguration { Id = config, TenantId = t, Code = "CON-STAT-C", Name = "PF", StatutoryType = StatutoryType.ProvidentFund, IsActive = true }); db.StatutoryConfigurationVersions.Add(new StatutoryConfigurationVersion { Id = configVersion, TenantId = t, StatutoryConfigurationId = config, EffectiveFrom = new DateOnly(2026, 1, 1), Status = StatutoryConfigurationStatus.Active, ConfigurationJson = "{}" }); db.PayrollStatutoryResults.Add(new PayrollStatutoryResult { Id = Guid.NewGuid(), TenantId = t, PayrollResultId = result, PayrollRunId = run, EmployeeId = e, StatutoryType = StatutoryType.ProvidentFund, JurisdictionCode = "IN", StatutoryConfigurationId = config, StatutoryConfigurationVersionId = configVersion, CalculationBasis = 10000, EmployeeAmount = 500, EmployerAmount = 500, TotalAmount = 1000, CreatedAtUtc = DateTime.UtcNow });
        await db.SaveChangesAsync(); await using var context = database.CreateContext(new TestTenantContext(t)); var compliance = new PayrollStatutoryComplianceService(context, new TestTenantContext(t), TimeProvider.System); var created = await compliance.CreatePeriodAsync(new PayrollCompliancePeriodRequest { JurisdictionCode = "IN", ComplianceType = PayrollComplianceType.ProvidentFund, PeriodStart = new DateOnly(2026, 9, 1), PeriodEnd = new DateOnly(2026, 9, 30) }); Assert.True(created.Succeeded, created.Message); return new(t, run, PeriodId: created.Value!.Id);
    }

