n, PayrollRunEmployeeId = runEmployee, EmployeeId = e, EmployeeSalaryAssignmentId = assignment, SalaryStructureId = structure, SalaryStructureVersionId = version, CalculationAttemptId = Guid.NewGuid(), PeriodStartDate = new DateOnly(2026, 9, 1), PeriodEndDate = new DateOnly(2026, 9, 30), EmploymentSnapshotDate = new DateOnly(2026, 9, 30), CalendarDays = 30, EligibleDays = 30, CurrencyCode = "INR", GrossEarnings = 10000, TotalDeductions = 1000, NetPay = 9000, Status = PayrollResultStatus.Calculated, IsCurrent = true }); db.PayrollRetroCases.Add(new PayrollRetroCase { Id = caseId, TenantId = t, EmployeeId = e, TriggerType = PayrollRetroTriggerType.ManualCorrection, EffectiveFrom = new DateOnly(2026, 9, 1), Status = PayrollRetroStatus.Approved, DetectedAtUtc = DateTime.UtcNow }); db.PayrollRetroResults.Add(new PayrollRetroResult { Id = resultId, TenantId = t, PayrollRetroCaseId = caseId, EmployeeId = e, OriginalPayrollRunId = originalRun, OriginalPayrollResultId = resultId, PeriodStartDate = new DateOnly(2026, 9, 1), PeriodEndDate = new DateOnly(2026, 9, 30), OriginalGross = 10000, CorrectedGross = 10100, GrossDifference = 100, OriginalDeductions = 1000, CorrectedDeductions = 1000, OriginalNet = 9000, CorrectedNet = 9100, NetDifference = 100, CurrencyCode = "INR", CalculatedAtUtc = DateTime.UtcNow, Components = { new PayrollRetroComponent { Id = Guid.NewGuid(), TenantId = t, ComponentCode = "ARREAR", ComponentName = "Arrear", OriginalAmount = 0, CorrectedAmount = 100, DifferenceAmount = 100, IsEarning = true, Sequence = 1 } } }); await db.SaveChangesAsync(); return new(t, originalRun, CaseId: caseId, ResultId: resultId, TargetRunId: targetRun);
